import { Injectable } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { Item } from './item.model';

@Injectable({ providedIn: 'root' })
export class ItemsService {
  constructor(private http: HttpClient) {}

  getItems() {
    this.http.get<Item[]>('/api/items');
  }
}

candidates.expected_answer:
Falta la palabra clave `return` en getItems(). El método ejecuta la llamada pero no devuelve nada, así que el componente recibe `undefined` y al intentar `.subscribe(...)` salta el error. Debe quedar así:

  getItems() {
    return this.http.get<Item[]>('/api/items');
  }

Sin `return`, el Observable se pierde y nadie puede suscribirse a él.

