import { Component, OnInit } from '@angular/core';
import { ItemsService } from './items.service';
import { Item } from './item.model';

@Component({
  selector: 'app-items',
  templateUrl: './items.component.html'
})
export class ItemsComponent implements OnInit {
  items: Item[] = [];

  constructor(private itemsService: ItemsService) {}

  ngOnInit(): void {
    this.itemsService.getItems();
  }
}

candidates.expected_answer:
Falta suscribirse al Observable. `HttpClient.get()` devuelve un Observable perezoso (frío): si nadie se suscribe, la petición HTTP no se llega a enviar y `items` se queda vacío. La corrección es:

  ngOnInit(): void {
    this.itemsService.getItems().subscribe(items => this.items = items);
  }

Al suscribirse, Angular envía la petición y asigna la respuesta a `items`.

